import React, { useState, useEffect, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { productService } from '../services/api';
import ProductCard from '../components/ProductCard';
import './BoutiquePage.css';

function BoutiquePage() {
  const [searchParams] = useSearchParams();
  const [products, setProducts] = useState([]);
  const [filteredProducts, setFilteredProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    category: searchParams.get('category') || '',
    priceMin: 0,
    priceMax: 1000000,
    search: searchParams.get('search') || '',
    sort: 'recent'
  });
  const [categories, setCategories] = useState([]);

  useEffect(() => {
    loadProducts();
  }, []);

  const loadProducts = useCallback(async () => {
    try {
      const res = await productService.getAll();
      setProducts(res.data);
      const uniqueCategories = [...new Set(res.data.map(p => p.categorie))];
      setCategories(uniqueCategories);
    } catch (error) {
      console.error('Erreur:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  const applyFilters = useCallback(() => {
    let filtered = products;

    if (filters.category) {
      filtered = filtered.filter(p => p.categorie === filters.category);
    }

    filtered = filtered.filter(p =>
      p.prix >= filters.priceMin && p.prix <= filters.priceMax
    );

    if (filters.search) {
      filtered = filtered.filter(p =>
        p.nom.toLowerCase().includes(filters.search.toLowerCase()) ||
        p.description.toLowerCase().includes(filters.search.toLowerCase())
      );
    }

    switch (filters.sort) {
      case 'price_asc':
        filtered.sort((a, b) => a.prix - b.prix);
        break;
      case 'price_desc':
        filtered.sort((a, b) => b.prix - a.prix);
        break;
      case 'popular':
        filtered.sort((a, b) => (b.rating || 0) - (a.rating || 0));
        break;
      default:
        filtered.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
    }

    setFilteredProducts(filtered);
  }, [products, filters]);

  useEffect(() => {
    applyFilters();
  }, [applyFilters]);

  return (
    <div className="boutique-page">
      <div className="container-fluid p-4">
        <div className="row">
          <div className="col-md-3 mb-4">
            <div className="filters p-3 bg-light rounded">
              <h4 className="mb-3">Filtres</h4>

              <div className="mb-3">
                <h6>Catégories</h6>
                <div className="form-check">
                  <input
                    className="form-check-input"
                    type="radio"
                    name="category"
                    id="all_categories"
                    value=""
                    checked={filters.category === ''}
                    onChange={(e) => setFilters({ ...filters, category: '' })}
                  />
                  <label className="form-check-label">Toutes</label>
                </div>
                {categories.map(cat => (
                  <div key={cat} className="form-check">
                    <input
                      className="form-check-input"
                      type="radio"
                      name="category"
                      id={cat}
                      value={cat}
                      checked={filters.category === cat}
                      onChange={(e) => setFilters({ ...filters, category: cat })}
                    />
                    <label className="form-check-label">{cat}</label>
                  </div>
                ))}
              </div>

              <hr />

              <div className="mb-3">
                <h6>Trier par</h6>
                <select
                  className="form-select"
                  value={filters.sort}
                  onChange={(e) => setFilters({ ...filters, sort: e.target.value })}
                >
                  <option value="recent">Plus récent</option>
                  <option value="popular">Populaire</option>
                  <option value="price_asc">Prix: Bas vers Haut</option>
                  <option value="price_desc">Prix: Haut vers Bas</option>
                </select>
              </div>
            </div>
          </div>

          <div className="col-md-9">
            <h3 className="mb-4">Produits ({filteredProducts.length})</h3>

            {loading ? (
              <div className="text-center">
                <div className="spinner-border" role="status">
                  <span className="visually-hidden">Chargement...</span>
                </div>
              </div>
            ) : filteredProducts.length > 0 ? (
              <div className="row">
                {filteredProducts.map(product => (
                  <div key={product.id} className="col-md-4 mb-4">
                    <ProductCard product={product} />
                  </div>
                ))}
              </div>
            ) : (
              <div className="alert alert-info">
                Aucun produit ne correspond à vos filtres.
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default BoutiquePage;
